#include <boost/icl/interval.hpp>
#include <boost/icl/interval_set.hpp>

using namespace boost::icl;
using R = discrete_interval<int>;        // bounds fixed at runtime

R booking = R::closed(10, 20);           // [10,20]
R slot    = R::right_open(20, 30);       // [20,30)
bool clash = intersects(booking, slot);  // false: they only touch

interval_set<int> taken;
taken += booking;

